# Chapters 16-31.
from content_a import chapter, T, W, Q, CH

chapter(id='renpoint', num=16, part='III', section='B · Compositional theory', title='Counterpoint pedagogy in the Renaissance', author='Peter Schubert', pages='503–533',
  summary='For almost two centuries, Renaissance teachers explained the elaboration of a given line (soggetto) with remarkably consistent principles. They moved from note-against-note formulas to florid writing, imitation, double counterpoint and four-part sonority.',
  points=['Sources fall into four groups: 15th-century writers (Ugolino, Tinctoris 1477, Ramis, Gaffurio); 16th-century Italians (Aron, Lusitano, Vicentino, Zarlino, Zacconi, Artusi, Cerone, Diruta); Spaniards (Sancta Maria, Montaños, Bermudo); Germans and English (Burmeister, Morley, Campion).',
          '<b>Contrapunctus simplex</b>: note against note, consonances only. Pupils memorized lists of two-note progressions (e.g., from a sixth to an octave) for improvisation.',
          'Modal considerations: Aron objects to a b♭ in the bass that would change its melodic species. Cadences must suit the mode.',
          '<b>Florid (diminutus) counterpoint</b>: Tinctoris\'s eight general rules, including variety (varietas). Dissonances pass on weak parts of the beat or appear as prepared syncopations (suspensions).',
          'Motives (inventioni, passaggi) and imitation (contrapunto fugato); improvised canon in Lusitano (1553).',
          '<b>Double counterpoint</b> at the octave, tenth and twelfth (Zarlino; Chiodino 1610).',
          'Sancta Maria (1565) teaches four-part writing as cycles of consonant sonorities (5/3, 6/3), a step toward chordal thinking.'],
  rules=[{'text': 'All concords must be used; begin and end with perfect concords; avoid successive perfect concords of the same kind; prefer contrary motion; seek variety.', 'who': 'Tinctoris, Liber de arte contrapuncti (1477), general rules (paraphrase)'},
         {'text': 'Dissonance is allowed in florid counterpoint only on unaccented parts of the beat or as a syncopation prepared and resolved down by step.', 'who': 'Tinctoris; Zarlino (1558)'}],
  guidelines=[{'text': 'Learn short memorized progressions (e.g., third–fifth, sixth–octave) to improvise against a cantus firmus.', 'who': '15th-c. teachers (Ugolino, Tinctoris)'}],
  terms=[('soggetto', 'The given or chosen subject that the counterpoint elaborates.'),
         ('contrapunctus simplex / diminutus', 'Note-against-note / florid counterpoint.'),
         ('double (invertible) counterpoint', 'Counterpoint that still works when the voices are exchanged at a given interval.'),
         ('cantare super librum', 'Improvised counterpoint sung over a chant from the book.')],
  theorists=[T('Johannes Tinctoris', 'c. 1435–1511', [W('Liber de arte contrapuncti', '1477')], 'Simple vs florid counterpoint; eight rules.'),
             T('Vicente Lusitano', 'fl. 1550s', [W('Introduttione facilissima', '1553')], 'Improvised canon.'),
             T('Gioseffo Zarlino', '1517–90', [W('Le istitutioni harmoniche', '1558')], 'Systematic counterpoint, Part III.'),
             T('Tomás de Sancta Maria', 'd. 1570', [W('Arte de tañer fantasía', '1565')], 'Four-part sonorities for keyboard.'),
             T('Thomas Morley', '1557/8–1602', [W('A Plaine and Easie Introduction to Practicall Musicke', '1597')], 'English pedagogy in dialogue form.')],
  quiz=[Q('Contrapunctus simplex means…', ['florid counterpoint', 'note-against-note consonant counterpoint', 'invertible counterpoint', 'canon'], 1, 'As opposed to diminutus.'),
        Q('Who taught four-part writing by cycles of sonorities in 1565?', ['Zarlino', 'Sancta Maria', 'Morley', 'Aron'], 1, 'Arte de tañer fantasía.')],
  tools=['organum'], links=['fux', 'fugue'])

chapter(id='performance', num=17, part='III', section='B · Compositional theory', title='Performance theory', author='Albert Cohen', pages='534–553',
  summary='Theory usually takes the written score as its object. Cohen looks at the other tradition, theories of performance: improvised counterpoint, Mersenne\'s interviews with performers, thoroughbass, division and ornament manuals, partimento, and the 18th-century performance treatises.',
  points=['The Greeks already separated practice (performance, composition, education) from theory (science, technique, criticism).',
          'Improvised vocal counterpoint is described by Lusitano (1553), Vicentino (1555) and Zarlino (1558).',
          'Mersenne\'s <i>Harmonie universelle</i> (1636–37) records what Parisian performers actually did (lute, viol, voice).',
          'Thoroughbass: Viadana (1602) and Agazzari\'s <i>Del sonare sopra\'l basso</i> (1607), which divides instruments into "foundation" and "ornament".',
          'Division manuals (Ortiz 1553; Simpson\'s <i>Division-Violist</i> 1659) teach ornamenting a simple line. Partimento and "preluding" join bass-based improvisation to composition.',
          'The great 18th-century treatises (Couperin, Quantz, C. P. E. Bach, L. Mozart) make performance itself a subject of theory. Recordings and electronic media later shift attention to performance as text.'],
  terms=[('thoroughbass', 'Accompaniment improvised over a figured bass.'),
         ('divisions / diminutions', 'Ornamental elaboration of a simple line into faster notes.'),
         ('partimento', 'A bass (often unfigured) used to teach improvisation and composition, especially in Naples.')],
  theorists=[T('Lodovico Viadana', 'c. 1560–1627', [W('Cento concerti ecclesiastici', '1602')], 'Early printed basso continuo.'),
             T('Agostino Agazzari', 'c. 1580–1642', [W('Del sonare sopra\'l basso', '1607')], 'Instruments of foundation and of ornament.'),
             T('Christopher Simpson', 'c. 1602–69', [W('The Division-Violist', '1659')], 'Division technique.'),
             T('Johann Joachim Quantz', '1697–1773', [W('Versuch einer Anweisung die Flöte traversiere zu spielen', '1752')], 'Performance as theory.'),
             T('C. P. E. Bach', '1714–88', [W('Versuch über die wahre Art das Clavier zu spielen', '1753–62')], 'Keyboard performance and accompaniment.')],
  quiz=[Q('Agazzari (1607) divided continuo instruments into…', ['strings and winds', 'foundation and ornament', 'loud and soft', 'solo and tutti'], 1, 'Del sonare sopra\'l basso.')],
  links=['hip', 'partimento'])

chapter(id='gradus', num=18, part='III', section='B · Compositional theory', title='Steps to Parnassus: contrapuntal theory in 1725, precursors and successors', author='Ian Bent', pages='554–602',
  summary='For 250 years Fux\'s <i>Gradus ad Parnassum</i> (1725) has been the reference point of counterpoint teaching. Bent shows what Fux inherited (the motion rules, the species), what he systematized, and how later writers rewrote him, from Martini and Albrechtsberger to Schenker and Jeppesen.',
  points=['The <i>Gradus</i> is a Latin dialogue between Aloysius (Palestrina) and the student Josephus, a guided ascent like Virgil leading Dante. Mizler translated it into German (1742), and there was an Italian version (1761).',
          'Fux sorts motion into direct, contrary and oblique, and maps it onto four rules about moving between perfect and imperfect consonances. Bent stresses that the substance of these rules goes back to Zarlino and earlier.',
          'The species existed before Fux (Diruta, Banchieri\'s <i>Cartella</i> 1614, Zacconi, Bononcini 1673). Fux made them a graded method: 1 note against note; 2 two against one; 3 four against one; 4 syncopation (ligature); 5 florid.',
          'Fux continues with three and four parts, imitation, fugue and double counterpoint, all in the modes.',
          'Successors include Martini\'s <i>Esemplare</i> (1774–75), Albrechtsberger (1790; Beethoven\'s teacher), Cherubini, Bellermann, Schenker\'s <i>Kontrapunkt</i> (1910–22) and Jeppesen (1930–31). Haydn, Mozart and Beethoven all studied the <i>Gradus</i>.'],
  rules=[{'text': 'From perfect to perfect consonance: contrary or oblique motion.', 'who': 'Fux, Gradus (1725)'},
         {'text': 'From perfect to imperfect consonance: any motion.', 'who': 'Fux'},
         {'text': 'From imperfect to perfect consonance: contrary or oblique motion.', 'who': 'Fux'},
         {'text': 'From imperfect to imperfect consonance: any motion.', 'who': 'Fux'},
         {'text': 'Two perfect consonances of the same kind in succession are forbidden.', 'who': 'Zarlino (1558), restated by Fux'}],
  terms=[('species counterpoint', 'Graded exercises against a cantus firmus: five species of rhythmic relation.'),
         ('cantus firmus', 'The given chant-like line in whole notes.'),
         ('ligature (4th species)', 'Syncopation producing suspensions.')],
  theorists=[T('Johann Joseph Fux', '1660–1741', [W('Gradus ad Parnassum', '1725')], 'Five species; four rules of motion.'),
             T('Adriano Banchieri', '1568–1634', [W('Cartella musicale', '1614')], 'Species-like paradigms.'),
             T('Lorenz Mizler', '1711–78', [W('Gradus (German trans.)', '1742')], 'German translator of Fux.'),
             T('Giovanni Battista Martini', '1706–84', [W('Esemplare o sia saggio … di contrappunto', '1774–75')], 'Counterpoint by annotated examples.'),
             T('Johann Georg Albrechtsberger', '1736–1809', [W('Gründliche Anweisung zur Composition', '1790')], 'Fux updated; Beethoven\'s teacher.'),
             T('Knud Jeppesen', '1892–1974', [W('Kontrapunkt', '1930–31')], 'Palestrina-style counterpoint.')],
  quiz=[Q('Moving from an imperfect to a perfect consonance, Fux allows…', ['any motion', 'contrary or oblique motion', 'only parallel motion', 'only oblique motion'], 1, 'Rule 3.'),
        Q('Fux\'s fourth species is…', ['four notes against one', 'syncopation (ligatures)', 'florid', 'note against note'], 1, 'Ligatures produce suspensions.'),
        Q('Who is Aloysius in the Gradus dialogue?', ['Fux himself', 'Palestrina', 'Zarlino', 'Josquin'], 1, 'The master representing Palestrina.')],
  links=['fux', 'fugue'])

chapter(id='twelvetone', num=19, part='III', section='B · Compositional theory', title='Twelve-tone theory', author='John Covach', pages='603–627',
  summary='Twelve-tone theory began among composers in the 1920s: Hauer\'s tropes and Schoenberg\'s method as introduced by Stein. It grew through the "modal" systems of the 1930s and 40s and, after 1945, became one of the founding subjects of American academic theory.',
  points=['Josef Matthias Hauer argued for twelve-tone music on gnostic grounds and discovered the 44 tropes (1921). Herbert Eimert\'s <i>Atonale Musiklehre</i> (1924) is a practical account.',
          'Erwin Stein\'s "Neue Formprinzipien" (1924) introduced Schoenberg\'s method. The Grundgestalt (basic shape) is the source of a work\'s material. Schoenberg himself wrote little until "Composition with Twelve Tones" (1941).',
          'Rows appear in four forms (prime, inversion, retrograde, retrograde inversion) at 12 transpositions.',
          '1930–45: Hill (1936), Krenek (1940) and Perle (1941) proposed twelve-tone "modes" and functional relations.',
          'After 1945: Leibowitz (1947), Rufer (1952), then Babbitt (combinatoriality, aggregates, invariants, time-points), Forte and Perle (<i>Twelve-Tone Tonality</i>, 1977). Covach asks whether twelve-tone theory has declined.'],
  rules=[{'text': 'All twelve pitch classes appear in a fixed order (the row) before any is repeated; the row may be used as P, I, R or RI at any transposition.', 'who': 'Schoenberg\'s method as described by Stein (1924)'},
         {'text': 'A row is hexachordally combinatorial if a transformed form\'s first hexachord is the complement of the original\'s first hexachord.', 'who': 'Babbitt'}],
  terms=[('row (series)', 'An ordering of the twelve pitch classes.'),
         ('P / I / R / RI', 'Prime, inversion, retrograde, retrograde inversion.'),
         ('trope', 'Hauer\'s unordered pair of complementary hexachords (44 types).'),
         ('combinatoriality', 'Property allowing two row forms to complete aggregates by hexachords.'),
         ('Grundgestalt', 'Basic shape from which a work\'s material derives (Schoenberg).')],
  theorists=[T('Josef Matthias Hauer', '1883–1959', [W('Vom Wesen des Musikalischen', '1920')], 'Tropes; gnostic twelve-tone theory.'),
             T('Herbert Eimert', '1897–1972', [W('Atonale Musiklehre', '1924')], 'Early practical twelve-tone text.'),
             T('Erwin Stein', '1885–1958', [W('"Neue Formprinzipien"', '1924')], 'First account of Schoenberg\'s method.'),
             T('Arnold Schoenberg', '1874–1951', [W('"Composition with Twelve Tones"', '1941')], 'The method and its rationale.'),
             T('George Perle', '1915–2009', [W('Twelve-Tone Tonality', '1977')], 'Cyclic sets and twelve-tone modes.'),
             T('Milton Babbitt', '1916–2011', [], 'Combinatoriality, invariance, time-point system.')],
  quiz=[Q('Who discovered the 44 tropes?', ['Schoenberg', 'Hauer', 'Babbitt', 'Krenek'], 1, 'Late 1921.'),
        Q('Who first published an account of Schoenberg\'s method (1924)?', ['Erwin Stein', 'Leibowitz', 'Rufer', 'Perle'], 0, '"Neue Formprinzipien".')],
  tools=['row-matrix'])

# ---------------- III C Time ----------------
chapter(id='notation', num=20, part='III', section='C · Time', title='The evolution of rhythmic notation', author='Anna Maria Busse Berger', pages='628–656',
  summary='Rhythmic notation made Western polyphony possible. Busse Berger follows it from the contextual rhythmic modes of Notre Dame, through Franco\'s fixed note values and the Ars nova\'s mensurations, to the Italian divisions and the Renaissance tactus.',
  points=['<b>Modal notation</b> (13th c.): Garlandia (c. 1250) gives six rhythmic modes, read from ligature patterns in context. Modes 1, 2 and 6 are the "correct" modes because they keep the long–breve proportion.',
          '<b>Franco of Cologne</b>, <i>Ars cantus mensurabilis</i> (c. 1280): each note shape has its own value (duplex long, long, breve, semibreve). Perfection is three tempora, with rules of imperfection and alteration; ligatures carry propriety and perfection.',
          '<b>Ars nova</b> (Vitry; de Muris\' <i>Notitia</i>, 1321): the minim; modus, tempus and prolation, each perfect or imperfect; mensuration signs; red notation.',
          '<b>Italian notation</b> (Marchetto\'s <i>Pomerium</i>, c. 1318): divisions of the breve (quaternaria, senaria, octonaria, duodenaria) and dots of division.',
          'The mensural system is a chain of values, each a multiple or divisor of the next, like the Roman system of weights. Later came proportions (Tinctoris) and the tactus as a steady beat measuring time.'],
  rules=[{'text': 'A long is perfect (3 breves) when followed by a long; a breve alone between longs makes the first imperfect, and two breves make the second "altered" (doubled).', 'who': 'Franco, Ars cantus mensurabilis (c. 1280) (paraphrase)'},
         {'text': 'Tempus (breve: semibreves) and prolation (semibreve: minims) may each be perfect (3) or imperfect (2); signs: circle = perfect tempus, half-circle = imperfect; dot = major prolation.', 'who': 'Ars nova (de Muris, Vitry)'}],
  terms=[('rhythmic modes', 'Six repeating long–short patterns in 13th-century notation.'),
         ('perfection', 'A group of three tempora (ternary unit), the norm of early mensural music.'),
         ('imperfection / alteration', 'Reducing a long by a breve / doubling the second of two breves.'),
         ('mensuration', 'The combination of modus, tempus and prolation, shown by a sign.'),
         ('tactus', 'The steady beat (down–up) by which Renaissance time was measured.')],
  theorists=[T('Johannes de Garlandia', 'fl. c. 1240–70', [W('De mensurabili musica', 'c. 1250')], 'Six rhythmic modes.'),
             T('Franco of Cologne', 'fl. mid–late 13th c.', [W('Ars cantus mensurabilis', 'c. 1280')], 'Note shapes with fixed values.'),
             T('Philippe de Vitry', '1291–1361', [W('Ars nova (attr.)', 'c. 1320')], 'Ars nova mensuration.'),
             T('Johannes de Muris', 'c. 1290–after 1344', [W('Notitia artis musicae', '1321')], 'Ars nova theory; minim.'),
             T('Marchetto of Padua', 'fl. 1305–19', [W('Pomerium', 'c. 1318')], 'Italian divisions.')],
  quiz=[Q('Which rhythmic modes did Garlandia call "correct" (recti)?', ['1, 2 and 6', '3, 4 and 5', 'all six', 'only mode 1'], 0, 'They keep the long–breve proportion.'),
        Q('Who gave each note shape a fixed value around 1280?', ['Garlandia', 'Franco of Cologne', 'Vitry', 'Marchetto'], 1, 'Ars cantus mensurabilis.'),
        Q('A circle with a dot means…', ['perfect tempus, major prolation', 'imperfect tempus, minor prolation', 'perfect modus', 'tactus'], 0, 'Modern 9/8.')],
  tools=['mensural'])

chapter(id='rhythm1819', num=21, part='III', section='C · Time', title='Theories of musical rhythm in the 18th and 19th centuries', author='William E. Caplin', pages='657–694',
  summary='As the mensural system gave way to bar lines, time signatures and accents, theorists had to explain the modern system of meter. Caplin traces the problem from Mattheson\'s sound-feet to Koch\'s phrase grammar and Riemann\'s upbeat-oriented system.',
  points=['Before the 17th century rhythm followed the mensural system and the tactus. Change came gradually, and proportions gave way to time signatures.',
          'Accent was tied to meter: good and bad notes (nota buona / cattiva), "struck" versus "passing" notes, linked to consonance and dissonance.',
          'Mattheson (<i>Der vollkommene Capellmeister</i>, 1739) borrows poetic feet (Klangfüße) for rhythm, though he never relates them consistently to meter.',
          'Kirnberger and Schulz (<i>Die Kunst des reinen Satzes</i>, 1771–79) discuss tempo giusto, kinds of meter, compound meters and phrase segments.',
          'Koch (<i>Versuch</i>, 1782–93): phrase units (Einschnitt, Absatz, Periode), punctuation, extension and compression, the norm of four-bar phrases.',
          '19th century: Momigny (upbeat-to-downbeat groupings, 1803–06), Hauptmann (dialectic of 2 and 3, 1853), Lussy (expressive accents, 1874), Westphal (a revival of ancient Greek metrics), Riemann (<i>Musikalische Dynamik und Agogik</i>, 1884; <i>System der musikalischen Rhythmik und Metrik</i>, 1903: upbeat orientation and eight-bar norm).'],
  rules=[{'text': 'In common time the first and third beats are good (accented), the second and fourth bad; dissonance belongs on good parts only when prepared.', 'who': '18th-c. German theory (Walther; Kirnberger)'}],
  guidelines=[{'text': 'Phrases are measured in bars like lines of verse; four-bar units are the norm, which may be extended or compressed.', 'who': 'Koch, Versuch (1782–93)'},
              {'text': 'Motives are upbeat-oriented: the weak beat leads into the strong one.', 'who': 'Riemann (1884, 1903)'}],
  terms=[('Klangfuß (sound-foot)', 'Mattheson\'s musical analogue of a poetic foot.'),
         ('Einschnitt / Absatz / Periode', 'Koch\'s phrase units, from smallest to largest.'),
         ('Auftaktigkeit', 'Riemann\'s principle that motives begin with an upbeat.'),
         ('agogics', 'Expressive timing (Riemann).')],
  theorists=[T('Johann Mattheson', '1681–1764', [W('Der vollkommene Capellmeister', '1739')], 'Sound-feet; rhetoric of melody.'),
             T('Johann Philipp Kirnberger', '1721–83', [W('Die Kunst des reinen Satzes in der Musik', '1771–79')], 'Meter types and tempo giusto.'),
             T('Heinrich Christoph Koch', '1749–1816', [W('Versuch einer Anleitung zur Composition', '1782–93')], 'Phrase grammar.'),
             T('Jérôme-Joseph de Momigny', '1762–1842', [W('Cours complet d\'harmonie et de composition', '1803–06')], 'Upbeat–downbeat cadential groups.'),
             T('Mathis Lussy', '1828–1910', [W('Traité de l\'expression musicale', '1874')], 'Expressive accentuation.'),
             T('Hugo Riemann', '1849–1919', [W('System der musikalischen Rhythmik und Metrik', '1903')], 'Upbeat motives; eight-bar norm.')],
  quiz=[Q('Koch\'s smallest phrase unit is the…', ['Periode', 'Absatz', 'Einschnitt', 'Satz'], 2, 'Einschnitt (incise).'),
        Q('Riemann\'s rhythmic theory emphasizes…', ['downbeat-initiated motives', 'upbeat orientation', 'additive rhythm', 'time-points'], 1, 'Auftaktigkeit.')],
  links=['hip'])

chapter(id='rhythm20', num=22, part='III', section='C · Time', title='Rhythm in twentieth-century theory', author='Justin London', pages='695–725',
  summary='Twentieth-century rhythmic theory split into several lines. One treats rhythm as motion and energy; one takes the Schenkerian view of rhythm emerging from voice leading; another uses the grouping-and-meter models of Cooper & Meyer and Lerdahl & Jackendoff. A further line comprises serial and composerly theories, alongside new cognitive work.',
  points=['Motion and energy: Kurth; Neumann\'s <i>Zeitgestalten</i>; Hasty\'s <i>Meter as Rhythm</i> (1997), where meter is projection.',
          'Schenker: the fundamental structure is arrhythmic, and rhythm arises in the middleground. Schachter\'s durational reduction and Rothstein\'s <i>Phrase Rhythm in Tonal Music</i> (1989) develop this.',
          'Yeston (1976) treats meter as the interaction of rhythmic strata, and metrical dissonance as conflicting levels (developed by Krebs).',
          'Cooper & Meyer (1960) analyse rhythmic groups on the model of poetic feet at architectonic levels. Lerdahl & Jackendoff (1983) separate grouping from meter, with well-formedness and preference rules.',
          'Kramer, <i>The Time of Music</i> (1988): hypermeter and linear versus nonlinear time.',
          'Composers\' theories: Messiaen (added values, non-retrogradable rhythms), Stockhausen ("…how time passes…"), Babbitt\'s time-point system. Lewin\'s transformational approach to rhythm.'],
  terms=[('hypermeter', 'Meter at the level of bars and groups of bars.'),
         ('grouping vs meter', 'Segmentation into units versus the pattern of strong and weak beats (GTTM).'),
         ('metrical dissonance', 'Conflict between metrical layers (grouping or displacement).'),
         ('projection', 'Hasty: a duration sets up the expectation of a matching duration.')],
  theorists=[T('Grosvenor Cooper & Leonard B. Meyer', '1911–79 / 1918–2007', [W('The Rhythmic Structure of Music', '1960')], 'Rhythmic groups as poetic feet on levels.'),
             T('Maury Yeston', 'b. 1945', [W('The Stratification of Musical Rhythm', '1976')], 'Rhythmic levels; consonance and dissonance of meter.'),
             T('Carl Schachter', 'b. 1932', [], 'Durational reduction; rhythm and linear analysis.'),
             T('Jonathan Kramer', '1942–2004', [W('The Time of Music', '1988')], 'Hypermeter; linear/nonlinear time.'),
             T('Christopher Hasty', 'b. 1949', [W('Meter as Rhythm', '1997')], 'Meter as process (projection).'),
             T('Olivier Messiaen', '1908–92', [W('Technique de mon langage musical', '1944')], 'Added values; non-retrogradable rhythms.')],
  quiz=[Q('Which theory separates grouping structure from metrical structure?', ['Riemann', 'Lerdahl & Jackendoff', 'Schenker', 'Mattheson'], 1, 'GTTM (1983).'),
        Q('For Schenker the Ursatz is…', ['in duple meter', 'arrhythmic', 'in hypermeter', 'iambic'], 1, 'Rhythm arises in the middleground.')])

# ---------------- III D Tonality ----------------
chapter(id='tonality', num=23, part='III', section='D · Tonality', title='Tonality', author='Brian Hyer', pages='726–752',
  summary='"Tonality" is a 19th-century word with many meanings. Hyer traces it from Choron and Fétis, through function theories and tonal grids, to Schenker and Schoenberg, and shows how its images of presence and centre shape what theorists hear.',
  points=['Choron first used the term in 1810, for the arrangement of dominant and subdominant around a tonic, and contrasted <i>tonalité moderne</i> with ancient tonality.',
          'Fétis popularized it in the 1830s–40s (his <i>Traité</i> of 1844). He said the idea came to him in the Bois de Boulogne in 1831. Tonality is the sum of necessary relations among the notes of the scale, its attractions are "metaphysical", and the dominant seventh in Monteverdi\'s <i>Stracciami pur il core</i> (1592) marks the birth of the modern kind.',
          'Hyer lists many senses of the word: pitch-centredness in general; tonal versus modal or atonal; the European practice of about 1680–1910; a synonym for "key"; and others.',
          'Tonal theories picture the tonic as presence and plenitude, and lay relations out on mental grids (Euler, Weber\'s key table, Oettingen and Riemann).',
          'Schenker: tonality is the composing-out of the tonic triad, including mixture. Schoenberg: monotonality and a chart of regions.'],
  terms=[('tonalité', 'Fétis: the necessary successive and simultaneous relations among the notes of a scale.'),
         ('tonic', 'The referential pitch or chord of a key.'),
         ('function', 'The role of a chord relative to the tonic (T, S, D).'),
         ('monotonality', 'Schoenberg: one tonic governs a whole piece; other keys are regions of it.')],
  theorists=[T('Alexandre Choron', '1771–1834', [], 'First use of "tonalité" (1810).'),
             T('François-Joseph Fétis', '1784–1871', [W('Traité complet de la théorie et de la pratique de l\'harmonie', '1844')], 'Popularized tonality; types unitonic → omnitonic.'),
             T('Arnold Schoenberg', '1874–1951', [W('Structural Functions of Harmony', '1954')], 'Monotonality and regions.')],
  quiz=[Q('Who first used "tonalité" as a theoretical term?', ['Fétis', 'Choron', 'Rameau', 'Riemann'], 1, 'In 1810.'),
        Q('Fétis located the birth of modern tonality in…', ['Bach\'s WTC', 'a Monteverdi madrigal of 1592', 'Rameau\'s Traité', 'Beethoven\'s Ninth'], 1, 'The unprepared dominant seventh in Stracciami pur il core.')],
  tools=['tonnetz', 'fundamental-bass'], links=['harmony'])

chapter(id='rameau', num=24, part='III', section='D · Tonality', title='Rameau and eighteenth-century harmonic theory', author='Joel Lester', pages='753–777',
  summary='Rameau joined separate strands into one theory of harmony: the triad as a unit, thoroughbass practice, and the directionality of cadences. Lester explains the fundamental bass, its successes and its problems, and the theory\'s reception.',
  points=['Before Rameau: 5/3 and 6/3 sonorities as building blocks (Zarlino; Lippius\'s "trias harmonica", 1612), thoroughbass rules, rules of the octave, and directed cadential voice leading.',
          '<i>Traité de l\'harmonie</i> (1722). Book I derives all chords from divisions of a string; triads and seventh chords are generated by a fundamental and are invertible. Book II shows how chords move.',
          'Fundamental bass: the succession of roots. Ideally it moves by fifths and thirds, the intervals generated by the string. A dissonance (the seventh) gives a chord its drive to resolve.',
          'Cadences: perfect (V7–I), irregular (IV with added sixth to I), and evaded or broken.',
          'Problem cases: "chords by supposition" (ninths, elevenths, with a bass below the fundamental); <i>double emploi</i> (the same chord read as IV with added sixth or as ii7); stepwise root motion.',
          'Later works: <i>Nouveau système</i> (1726), <i>Génération harmonique</i> (1737: the corps sonore and the harmonic series), <i>Démonstration</i> (1750). Reception: d\'Alembert\'s <i>Élémens</i> (1752), Marpurg, Sorge, Kirnberger (essential and inessential dissonances), Vogler, Tartini, Rousseau.'],
  rules=[{'text': 'Every chord has a fundamental (root); its inversions keep the same fundamental.', 'who': 'Rameau, Traité (1722)'},
         {'text': 'The fundamental bass should move by consonant intervals, chiefly fifths and thirds.', 'who': 'Rameau'},
         {'text': 'A dissonant seventh must resolve down by step.', 'who': 'Rameau (after contrapuntal tradition)'}],
  guidelines=[{'text': 'A chord such as F–A–C–D may be heard as IV with added sixth (going to I) or as ii7 (going to V): double emploi.', 'who': 'Rameau'}],
  terms=[('basse fondamentale', 'The succession of chord roots underlying the actual bass.'),
         ('renversement', 'Inversion: the same chord with another chord member in the bass.'),
         ('sixte ajoutée', 'Added sixth, characterizing the subdominant.'),
         ('double emploi', 'Double use: one chord with two possible fundamentals.'),
         ('supposition', 'A note "supposed" below the fundamental, explaining ninth and eleventh chords.')],
  theorists=[T('Johannes Lippius', '1585–1612', [W('Synopsis musicae novae', '1612')], '"Trias harmonica": the triad as a unit.'),
             T('Jean-Philippe Rameau', '1683–1764', [W('Traité de l\'harmonie', '1722'), W('Génération harmonique', '1737')], 'Fundamental bass, inversion, corps sonore.'),
             T('Jean le Rond d\'Alembert', '1717–83', [W('Élémens de musique', '1752')], 'Popularized Rameau.'),
             T('Johann Philipp Kirnberger', '1721–83', [W('Die wahren Grundsätze zum Gebrauch der Harmonie', '1773')], 'Essential vs inessential dissonances.')],
  quiz=[Q('Rameau\'s fundamental bass ideally moves by…', ['steps', 'fifths and thirds', 'tritones', 'octaves only'], 1, 'Intervals generated by the string.'),
        Q('What is double emploi?', ['two cadences in a row', 'one chord read with two fundamentals', 'parallel fifths', 'a doubled bass'], 1, 'IV add6 or ii7.'),
        Q('Rameau\'s Traité appeared in…', ['1700', '1722', '1737', '1750'], 1, '1722.')],
  tools=['fundamental-bass'], links=['harmony', 'partimento'])

chapter(id='harm19', num=25, part='III', section='D · Tonality', title='Nineteenth-century harmonic theory: the Austro-German legacy', author='David W. Bernstein', pages='778–811',
  summary='Rameau\'s lasting legacy was the idea that chords are generated on scale degrees of a key. Bernstein follows this idea through Vogler\'s Roman numerals and Weber\'s multiple meaning, Sechter\'s rigorous fundamental bass, Mayrberger\'s Tristan analysis, and the function and degree theories that led to Schenker and Schoenberg.',
  points=['Vogler (from 1776): triads on every scale degree, Roman-numeral thinking, and multiple meaning (Mehrdeutigkeit) of chords.',
          'Gottfried Weber (<i>Versuch einer geordneten Theorie der Tonsetzkunst</i>, 1817–21): upper- and lower-case Roman numerals, a table of key relationships, and multiple meaning used in analysis (e.g., the opening of Mozart\'s "Dissonance" Quartet).',
          'Sechter (<i>Grundsätze</i>, 1853–54): fundamental-bass progressions by fifths and thirds; stepwise root motion explained by an implied intermediate root; a diatonic-chromatic system. He taught Bruckner.',
          'Mayrberger (1878) analysed the Tristan Prelude with Sechterian fundamentals (the "Zwitterakkord").',
          'Riemann\'s function theory (T, S, D) competes with degree (Stufen) theory: Schenker\'s <i>Harmonielehre</i> (1906), Schoenberg\'s <i>Harmonielehre</i> (1911).'],
  rules=[{'text': 'Chords are named by the scale degree of their root (I–VII); upper case for major, lower case for minor.', 'who': 'Weber (1817–21)'},
         {'text': 'Every root progression is ultimately by fifth or third; an apparent step implies a hidden intermediate root.', 'who': 'Sechter (1853–54)'}],
  terms=[('Mehrdeutigkeit', 'Multiple meaning: a chord or pitch interpretable in several keys.'),
         ('Stufe', 'Scale degree; also a harmonic span governed by one degree (Schenker).'),
         ('Zwitterakkord', '"Hybrid chord" (Sechter/Mayrberger), mixing elements of two keys.')],
  theorists=[T('Georg Joseph Vogler', '1749–1814', [], 'Roman-numeral thinking; multiple meaning.'),
             T('Gottfried Weber', '1779–1839', [W('Versuch einer geordneten Theorie der Tonsetzkunst', '1817–21')], 'Roman numerals; key table.'),
             T('Simon Sechter', '1788–1867', [W('Die Grundsätze der musikalischen Komposition', '1853–54')], 'Strict fundamental-bass theory.'),
             T('Karl Mayrberger', '1828–81', [], 'Tristan analysis (1878).'),
             T('Hugo Riemann', '1849–1919', [W('Vereinfachte Harmonielehre', '1893')], 'Function theory.')],
  quiz=[Q('Who introduced upper- and lower-case Roman numerals with a key-relation table?', ['Vogler', 'Weber', 'Sechter', 'Riemann'], 1, 'Gottfried Weber, 1817–21.'),
        Q('Sechter explains stepwise root motion by…', ['a hidden intermediate root', 'double emploi', 'mixture', 'parallel fifths'], 0, 'All roots move by fifths or thirds.')],
  tools=['fundamental-bass', 'tonnetz'], links=['harmony'])

chapter(id='schenker', num=26, part='III', section='D · Tonality', title='Heinrich Schenker', author='William Drabkin', pages='812–846',
  summary='Schenker\'s theory can be summed up in one word, hierarchy. Drabkin explains four concepts (Stufe, composing-out, fundamental structure and structural levels) and the transformations that link the levels. He also covers Schenker\'s work as editor and his ideology, and the theory\'s American reception.',
  points=['Main works: <i>Harmonielehre</i> (1906), <i>Kontrapunkt</i> I–II (1910, 1922), <i>Der Tonwille</i> (1921–24), <i>Das Meisterwerk in der Musik</i> (1925–30), <i>Fünf Urlinie-Tafeln</i> (1932), <i>Der freie Satz</i> (1935).',
          '<b>Stufe</b>: a harmonic degree governing a span, not just a chord. The Harmonielehre analyses Bach\'s "Buß und Reu".',
          '<b>Auskomponierung</b> (composing-out): the tonic triad, the "chord of nature", is unfolded in time.',
          '<b>Ursatz</b>: the fundamental line (Urlinie) descends from ③, ⑤ or ⑧ to ①, over the bass arpeggiation I–V–I. It is the background.',
          '<b>Levels</b>: background, middleground (several layers), foreground. Transformations include linear progressions (Züge), unfolding, reaching-over, interruption (③–② ‖ ③–②–①), mixture, neighbour notes and concealed repetition.',
          'The Ursatz is arrhythmic. Schenker\'s organicism and cult of genius sit alongside nationalist views. The American reception (Jonas, Salzer 1952, Forte and others) turned the theory into an analytical method.'],
  rules=[{'text': 'The fundamental line descends stepwise to ① from ③, ⑤ or ⑧; the bass arpeggiates I–V–I beneath it.', 'who': 'Schenker, Der freie Satz (1935)'},
         {'text': 'A dissonant passing tone cannot itself be prolonged; only a consonance can be composed out.', 'who': 'Schenker (paraphrase)'}],
  terms=[('Ursatz', 'Fundamental structure: Urlinie plus Bassbrechung.'),
         ('Urlinie', 'Fundamental line descending to the tonic.'),
         ('Bassbrechung', 'Bass arpeggiation I–V–I.'),
         ('Prolongation', 'Elaboration that keeps a structural event in force across a span.'),
         ('Unterbrechung', 'Interruption: ③–② ‖ ③–②–①.')],
  theorists=[T('Heinrich Schenker', '1868–1935', [W('Harmonielehre', '1906'), W('Kontrapunkt', '1910–22'), W('Der freie Satz', '1935')], 'Hierarchical theory of tonal structure.'),
             T('Felix Salzer', '1904–86', [W('Structural Hearing', '1952')], 'American adaptation of Schenker.')],
  quiz=[Q('The Urlinie may begin on…', ['②, ④ or ⑥', '③, ⑤ or ⑧', 'any degree', 'only ⑤'], 1, 'Then descends to ①.'),
        Q('Interruption produces the pattern…', ['③–②–① ‖ ③–②–①', '③–② ‖ ③–②–①', '⑤–④ ‖ ③', '①–② ‖ ③'], 1, 'The first descent stops on ②.')],
  tools=['ursatz'], links=['harmony', 'fux'])

# ---------------- IV Descriptive ----------------
chapter(id='rhetoric', num=27, part='IV', section='A · Models of music analysis', title='Music and rhetoric', author='Patrick McCreless', pages='847–879',
  summary='Rhetoric was the West\'s original language for talking about discourse, and from the 16th century to about 1800 it shaped how music was taught and described. McCreless follows the musica poetica tradition, Burmeister\'s figures, Mattheson\'s plan for an oration, the decline of rhetoric around 1800, and its 20th-century revival.',
  points=['Classical rhetoric (Sicily c. 485 BCE; Aristotle; the <i>Rhetorica ad Herennium</i>; Cicero; Quintilian) has five canons: inventio, dispositio, elocutio, memoria and pronuntiatio. Elocutio includes the figures.',
          'Listenius\'s <i>Musica</i> (1537) adds <i>musica poetica</i>, the making of a finished, lasting work, to theorica and practica.',
          'Burmeister (1599, 1601, 1606) took figures from rhetorical elocutio (e.g., noema, anaploce, fuga realis, palilogia, climax) and analysed Lasso\'s <i>In me transierunt</i> as an oration with exordium, body and ending.',
          'Bernhard (c. 1660) explained figures as licensed dissonance treatment (passus duriusculus, superjectio, anticipatio…). The tradition continues with Walther, Mattheson (<i>Der vollkommene Capellmeister</i>, 1739: exordium, narratio, propositio, confirmatio, confutatio, peroratio) and Forkel.',
          'Rhetoric declined around 1800. It was revived in 20th-century historiography (Schering, Unger) and critiqued (Vickers). Its heirs include topic theory (Ratner 1980) and theories of expressive meaning.'],
  guidelines=[{'text': 'Arrange a piece like an oration: exordium, narratio, propositio, confirmatio, confutatio, peroratio.', 'who': 'Mattheson, Der vollkommene Capellmeister (1739)'},
              {'text': 'Musical figures depart from simple composition for expressive purposes, as rhetorical figures depart from plain speech.', 'who': 'Burmeister, Musica poetica (1606)'}],
  terms=[('musica poetica', 'Composition as the making of a finished work (Listenius 1537).'),
         ('Figurenlehre', 'Doctrine of musical-rhetorical figures.'),
         ('inventio / dispositio / elocutio', 'Finding ideas / arranging them / decorating them (with figures).'),
         ('Affektenlehre', 'Doctrine of the affections that music arouses.')],
  theorists=[T('Nikolaus Listenius', 'b. c. 1510', [W('Musica', '1537')], 'Introduced musica poetica.'),
             T('Joachim Burmeister', '1564–1629', [W('Musica poetica', '1606')], 'Musical-rhetorical figures; analysis of Lasso.'),
             T('Christoph Bernhard', '1628–92', [W('Tractatus compositionis augmentatus', 'c. 1660')], 'Figures as dissonance licences.'),
             T('Johann Mattheson', '1681–1764', [W('Der vollkommene Capellmeister', '1739')], 'Dispositio of a musical oration.'),
             T('Leonard Ratner', '1916–2011', [W('Classic Music', '1980')], 'Topic theory.')],
  quiz=[Q('Who introduced the term musica poetica (1537)?', ['Burmeister', 'Listenius', 'Mattheson', 'Bernhard'], 1, 'Musica (1537).'),
        Q('Burmeister analysed which motet rhetorically?', ['Josquin, Ave Maria', 'Lasso, In me transierunt', 'Palestrina, Sicut cervus', 'Byrd, Ave verum'], 1, 'Musica poetica (1606).')],
  links=['hip'])

chapter(id='form', num=28, part='IV', section='A · Models of music analysis', title='Form', author='Scott Burnham', pages='880–906',
  summary='The Formenlehre tradition centres on sonata form. Burnham traces it from Koch\'s description of an expanded binary plan, through Reicha\'s thematic diagrams and Marx\'s organic system of forms, to 20th-century theories of formal function and the Schenkerian view of form.',
  points=['Koch (<i>Versuch</i> vol. 3, 1793) describes the first movement as an expanded binary form built from punctuated phrases. Galeazzi (1796) names its melodic parts.',
          'Reicha (<i>Traité de haute composition</i>, 1824–26) gives the <i>grande coupe binaire</i>, analyses the <i>Figaro</i> overture, and treats "développement" as the working-out of ideas.',
          'Marx (<i>Lehre von der musikalischen Komposition</i>, 1837–47) derives all forms from the opposition of the closed Satz and the open Gang: Lied forms, five rondo forms, and sonata form with Hauptsatz, Seitensatz and Schlusssatz. Czerny\'s <i>School of Practical Composition</i> (c. 1848) spread the model.',
          '20th century: Schoenberg (sentence and period), Ratz, Tovey, Rosen, Caplin\'s formal functions, Hepokoski & Darcy\'s sonata theory, Lorenz on Wagner. Schenker derives form from the voice-leading structure.'],
  terms=[('Formenlehre', 'Doctrine of musical forms.'),
         ('Hauptsatz / Seitensatz', 'Main theme / subordinate theme (Marx).'),
         ('Satz / Gang', 'Marx: closed theme versus open, transitional passage.'),
         ('grande coupe binaire', 'Reicha\'s name for sonata form.')],
  theorists=[T('Heinrich Christoph Koch', '1749–1816', [W('Versuch', '1782–93')], 'Phrase-based description of forms.'),
             T('Francesco Galeazzi', '1758–1819', [W('Elementi teorico-pratici di musica', '1791–96')], 'Parts of the sonata melody.'),
             T('Anton Reicha', '1770–1836', [W('Traité de haute composition musicale', '1824–26')], 'Grande coupe binaire.'),
             T('Adolf Bernhard Marx', '1795–1866', [W('Die Lehre von der musikalischen Komposition', '1837–47')], 'Organic system of forms; "Sonatenform".'),
             T('Carl Czerny', '1791–1857', [W('School of Practical Composition', 'c. 1848')], 'Popular sonata-form model.')],
  quiz=[Q('Marx derives forms from the opposition of…', ['tonic and dominant', 'Satz and Gang', 'theme and variation', 'exposition and recap'], 1, 'Closed theme vs open passage.'),
        Q('Reicha called sonata form…', ['Sonatenform', 'grande coupe binaire', 'rondo', 'Bar form'], 1, 'Traité de haute composition (1824–26).')])

chapter(id='thematic', num=29, part='IV', section='A · Models of music analysis', title='Thematic and motivic analysis', author='Jonathan Dunsby', pages='907–926',
  summary='Western music is inherently melodic, and much analysis tracks themes and motives. Dunsby surveys Schoenberg\'s developing variation, Réti\'s thematic process, Keller\'s functional analysis, Schenker\'s motivic parallelisms, and semiotic paradigmatic analysis.',
  points=['"Theme" was in use by the 17th century and "motive" became common later. Themes and motives are the material of developing variation.',
          'Schoenberg: Grundgestalt and developing variation ("Brahms the Progressive").',
          'Réti, <i>The Thematic Process in Music</i> (1951): one thematic kernel unifies a whole work (e.g., Beethoven\'s Op. 135).',
          'Hans Keller\'s functional analysis: wordless analytical scores that show unity behind contrast.',
          'Semiotics: Ruwet\'s paradigmatic analysis of a medieval flagellant song (1972), Nattiez\'s tripartition. Signs can be described synchronically or diachronically, and paradigmatically or syntagmatically.'],
  terms=[('developing variation', 'Continuous transformation of a motive to generate new material (Schoenberg).'),
         ('paradigmatic analysis', 'Sorting segments into columns of equivalence (Ruwet, Nattiez).'),
         ('thematic process', 'Réti: derivation of all themes from one source.')],
  theorists=[T('Rudolph Réti', '1885–1957', [W('The Thematic Process in Music', '1951')], 'Thematic unity across a work.'),
             T('Hans Keller', '1919–85', [], 'Functional analysis.'),
             T('Nicolas Ruwet', '1932–2001', [W('Langage, musique, poésie', '1972')], 'Paradigmatic analysis.'),
             T('Jean-Jacques Nattiez', 'b. 1945', [], 'Semiology; tripartition.')],
  quiz=[Q('Who wrote The Thematic Process in Music (1951)?', ['Keller', 'Réti', 'Schoenberg', 'Ruwet'], 1, 'Rudolph Réti.')])

chapter(id='energetics', num=30, part='IV', section='B · Music psychology', title='Energetics', author='Lee Rothfarb', pages='927–955',
  summary='Energetics treats music as motion, force and tension. Rothfarb traces dynamic metaphors from Aristoxenus\' dynameis and medieval intervals that "seek" resolution, through Marx and Fétis, to Halm and Kurth around 1900, and on to later heirs.',
  points=['Musical motion is intuitively obvious but hard to define: pitches are discrete plateaus, yet we hear movement.',
          'Ancient and medieval roots: Aristoxenus\' "functions" (dynameis) of notes; 14th- and 15th-century intervals that "desire" a following interval.',
          '19th century: Marx (energy of the Hauptsatz), Fétis and Vivier (tendencies and attractions), Lipps, Riemann.',
          'August Halm (<i>Von zwei Kulturen der Musik</i>, 1913): fugue and sonata as two cultures. Music has a will of its own, and form is the obligation to follow it.',
          'Ernst Kurth: <i>Grundlagen des linearen Kontrapunkts</i> (1917), Bach\'s melody as kinetic energy; <i>Romantische Harmonik</i> (1920), the Tristan crisis; <i>Bruckner</i> (1925); <i>Musikpsychologie</i> (1931). Also Mersmann\'s graphs of dynamic form.'],
  terms=[('energetics', 'Theory of music as motion, force and tension.'),
         ('kinetic energy (Kurth)', 'The felt drive of melodic lines.'),
         ('tendency tone', 'A pitch that "wants" to resolve (Fétis, Vivier).')],
  theorists=[T('August Halm', '1869–1929', [W('Von zwei Kulturen der Musik', '1913')], 'Fugue and sonata as two cultures; music\'s will.'),
             T('Ernst Kurth', '1886–1946', [W('Grundlagen des linearen Kontrapunkts', '1917'), W('Romantische Harmonik und ihre Krise in Wagners Tristan', '1920')], 'Linear energy; Romantic harmony.'),
             T('Hans Mersmann', '1891–1971', [], 'Phenomenology and dynamic graphs of form.'),
             T('Victor Zuckerkandl', '1896–1965', [W('Sound and Symbol', '1956')], 'Dynamic qualities of tones.')],
  quiz=[Q('Kurth\'s 1917 book concerns…', ['Bach\'s linear counterpoint', 'Rameau\'s harmony', 'Greek modes', 'twelve-tone rows'], 0, 'Grundlagen des linearen Kontrapunkts.')],
  links=['fugue'])

chapter(id='psychology', num=31, part='IV', section='B · Music psychology', title='The psychology of music', author='Robert Gjerdingen', pages='956–981',
  summary='Music psychology asks how the mind perceives, imagines, performs and evaluates music. Gjerdingen traces it from philosophical roots through Wundt\'s laboratory and the Stumpf controversy, Gestalt and American functionalism (Seashore), to Meyer, Narmour and the cognitive revolution.',
  points=['Roots in philosophy: Locke, Hume and associationism; Comte\'s positivism. Basevi\'s 1862 harmony treatise rests on psychological premises.',
          'Wundt founded a laboratory (Leipzig, 1879). His student Lorenz\'s interval experiments sparked a bitter controversy with Stumpf (1890–91).',
          'Gestalt psychology (Wertheimer, Köhler, Koffka) supplied grouping laws later used by Meyer.',
          'American functionalism: Seashore\'s measures of musical talent (1919) and <i>Psychology of Music</i> (1938).',
          'Meyer, <i>Emotion and Meaning in Music</i> (1956): expectation and Gestalt laws such as good continuation. Narmour\'s implication–realization model (1990, 1992).',
          'Cognitive science: Krumhansl\'s tonal hierarchies, Bregman\'s auditory scene analysis, Lerdahl & Jackendoff, and schema-based approaches.'],
  terms=[('Gestalt laws', 'Principles of perceptual grouping: proximity, similarity, good continuation.'),
         ('implication–realization', 'Narmour: melodic intervals imply continuations that are realized or denied.'),
         ('Lipps–Meyer law', 'Intervals whose ratio ends on a power of 2 sound final (tend to the lower note).')],
  theorists=[T('Wilhelm Wundt', '1832–1920', [], 'Experimental psychology laboratory (1879).'),
             T('Carl Seashore', '1866–1949', [W('The Psychology of Musical Talent', '1919'), W('Psychology of Music', '1938')], 'Measured musical abilities.'),
             T('Leonard B. Meyer', '1918–2007', [W('Emotion and Meaning in Music', '1956')], 'Expectation theory.'),
             T('Eugene Narmour', 'b. 1939', [W('The Analysis and Cognition of Basic Melodic Structures', '1990')], 'Implication–realization.')],
  quiz=[Q('Emotion and Meaning in Music (1956) is by…', ['Seashore', 'Meyer', 'Narmour', 'Stumpf'], 1, 'Leonard B. Meyer.'),
        Q('Who measured "musical talent" with standardized tests?', ['Wundt', 'Seashore', 'Helmholtz', 'Kurth'], 1, '1919.')])
